printf '%s\n' 'import argparse' 'import json' 'import sys' 'from pathlib import Path' '' 'p = argparse.ArgumentParser()' 'p.add_argument("config")' 'p.add_argument("--env", choices=["dev", "staging", "prod"], default="dev")' 'a = p.parse_args()' 'try:' '    cfg = json.loads(Path(a.config).read_text())' 'except (OSError, ValueError):' '    sys.exit("error: cannot read config")' 'for k in ("app", "defaults"):' '    if k not in cfg:' '        sys.exit("error: missing key: " + k)' 'out = {**cfg["defaults"], **cfg.get("environments", {}).get(a.env, {})}' 'Path("resolved.json").write_text(json.dumps(out, indent=4, sort_keys=True))' > build_config.py
